<header class="admin-top"><div><p>M15 · Events</p><h1>Events desk</h1></div><a class="admin-secondary" href="<?=pm_e(pm_url('/events'))?>" target="_blank" rel="noopener">Open public Events</a></header>
<section class="admin-panel"><div class="admin-panel-head"><div><h2>Publish event</h2><p>Create a structured public event with source provenance.</p></div></div>
<form class="admin-form utility-form" data-create-event><label>Title<input name="title" required></label><label>Venue<input name="venue" required></label><label>Area<input name="area" value="Pune"></label><label>Category<input name="category" value="community"></label><label>Starts<input name="starts_at" type="datetime-local" required></label><label>Ends<input name="ends_at" type="datetime-local"></label><label>Source label<input name="source_label"></label><label>Source URL<input name="source_url" type="url"></label><label class="admin-span2">Summary<textarea name="summary" rows="4"></textarea></label><label><input name="is_public" type="checkbox" checked> Publish publicly</label><button class="admin-primary" type="submit">Publish event</button></form></section>
